/**
 * A VERIFIED HubSpot crm_event delivery. Listen for it in the app.
 * ONE endpoint serves every tenant: route it by portalId (routeKeys()), only to a
 * connection your app minted, and drop an unknown key with the 2xx already sent.
 */
final class CrmEventReceived
{
    /** @param array<string,list<string|null>> $headers */
    public function __construct(
        public readonly mixed $payload,
        public readonly array $headers = [],
    ) {}

    /** Every portalId in the payload ([].portalId); a batch carries one per item. */
    public function routeKeys(): array
    {
        $values = [$this->payload];
        foreach (explode('.', '[].portalId') as $segment) {
            $next = [];
            foreach ($values as $value) {
                if ($segment === '[]') {
                    if (is_array($value)) {
                        array_push($next, ...array_values($value));
                    }
                } elseif (is_array($value) && array_key_exists($segment, $value)) {
                    $next[] = $value[$segment];
                }
            }
            $values = $next;
        }

        return array_values(array_unique(array_filter($values, 'is_scalar')));
    }
}
